import {datasets,lessons,exercises,syllabusLinks} from './curriculum.js';
import {createEngine} from './engine.js';
import {gradeSql} from './grader.js';
import {readState,STORAGE_KEY,mergeBackup,validateBackup,recordAttempt} from './state.js';

const appBase=new URL('../',import.meta.url);
const assetUrl=path=>new URL(path,appBase).href;
const loaded=readState();let state=loaded.state;
const app=document.querySelector('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',code:'m8 7-5 5 5 5m8-10 5 5-5 5m-3-14-2 20',book:'M12 6C9 3 5 3 2 4v15c4-1 7-1 10 2m0-15c3-3 7-3 10-2v15c-4-1-7-1-10 2V6',grid:'M3 3h7v7H3Zm11 0h7v7h-7ZM3 14h7v7H3Zm11 0h7v7h-7Z',chart:'M4 3v18h17M8 16v-4m5 4V8m5 8V5',arrow:'M4 12h15m-6-6 6 6-6 6',play:'m8 4 12 8-12 8Z',check:'m5 12 4 4L19 6',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',search:'m16 16 5 5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',bookmark:'M6 3h12v18l-6-4-6 4Z',database:'M4 5c0-4 16-4 16 0S4 9 4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0',sun:'M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 17v4h16v-4',close:'m6 6 12 12M6 18 18 6',help:'M9 8a3 3 0 1 1 4 3c-1 1-1 1-1 3m0 3h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',reset:'M3 4v6h6M4 9a9 9 0 1 1 0 8',link:'M9 15 15 9m-7 4-2 2a4 4 0 0 0 6 6l3-3m-6-9 3-3a4 4 0 0 1 6 6l-2 2',chevron:'m9 5 7 7-7 7'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.code}"/></svg>`;
let SQL,engineError,labEngine,labDataset=state.lab?.dataset||datasets[0].id,labSql=state.lab?.sql||'SELECT * FROM STUDENT;',labResult=null;
let editorDirty=false;let busy=false,activeId=null,feedback=null,result=null,exerciseTables=null,tableIndex=0,hintsShown=0,solutionSeen=false,viewMode='data',sourceFilter='all',offlineReady=false;
let filters={search:'',status:'all',kind:'all'},saveTimer,toastTimer,examTimer;
let evidence=[];
const nav=[['home','home','概览'],['practice','code','动手练习'],['lab','database','SQL 实验室'],['learn','book','学习指南'],['sources','grid','语法参考']];
const byId=id=>exercises.find(e=>e.id===id);
const datasetById=id=>datasets.find(d=>d.id===id)||datasets[0];
const visibleExercises=()=>exercises.filter(e=>e.level===state.level);
const route=()=>decodeURIComponent(location.hash.slice(1)||'home').split('/');
function go(to){if(location.hash===`#${to}`){render();return;}location.hash=to;}
function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));return true;}catch{toast('无法保存到浏览器。请在「学习记录」中导出备份，避免丢失进度。',true);return false;}}
function toast(message,error=false){const el=document.querySelector('#toast');el.textContent=message;el.className=`show ${error?'error':''}`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='',5000);}
function download(name,body,type='application/json'){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([body],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function progress(){const list=visibleExercises();return {total:list.length,done:list.filter(e=>state.attempts[e.id]?.passed).length,independent:list.filter(e=>state.attempts[e.id]?.independent).length,wrong:list.filter(e=>state.attempts[e.id]?.tries>0&&!state.attempts[e.id].lastPassed).length};}
function nextExercise(){return byId(state.lastExercise)?.level===state.level&&!state.attempts[state.lastExercise]?.passed?byId(state.lastExercise):visibleExercises().find(e=>!state.attempts[e.id]?.passed)||visibleExercises()[0];}
function badge(e){return state.attempts[e.id]?.independent?'<span class="badge success">已掌握</span>':state.attempts[e.id]?.passed?'<span class="badge">已完成 · 辅助</span>':state.attempts[e.id]?.tries>0?'<span class="badge warm">再试一次</span>':`<span class="badge muted">${['','入门','进阶','挑战'][e.difficulty||1]}</span>`;}
function shell(content,current){document.documentElement.dataset.theme=state.theme;app.innerHTML=`
  <aside class="sidebar">
    <a href="#home" class="brand" aria-label="QueryPath 首页"><span class="brand-mark">${icon('database')}</span><span>QueryPath<small>把 SQL 考点学明白</small></span></a>
    <div class="workspace-label">YOUR WORKSPACE</div>
    <nav aria-label="主导航">${nav.map(([id,i,title])=>`<a href="#${id}" aria-label="${title}" title="${title}" class="nav-item ${current===id?'active':''}" ${current===id?'aria-current="page"':''}>${icon(i)}<span>${title}</span>${current===id?'<span class="nav-dot"></span>':''}</a>`).join('')}</nav>
    <div class="sidebar-bottom"><a class="nav-item ${current==='progress'?'active':''}" href="#progress">${icon('chart')}<span>学习记录与备份</span></a><div class="local-note"><span class="status-dot"></span><span>${offlineReady?'离线学习已就绪':navigator.onLine?'进度保存在这台设备':'当前离线'}</span></div><div class="sidebar-foot"><span>每一个查询，都是进步。</span><button class="icon-button" data-action="theme" aria-label="切换${state.theme==='dark'?'浅色':'深色'}模式">${icon('sun')}</button></div></div>
  </aside>
  <div class="app-body"><header class="topbar"><div class="breadcrumb">学习空间 <span>/</span> <strong>${({home:'概览',practice:'动手练习',exercise:'动手练习',learn:'学习指南',lesson:'学习指南',lab:'SQL 实验室',sources:'语法参考',progress:'学习记录',exam:'限时挑战'})[current]||'学习空间'}</strong></div><div class="topbar-actions"><label class="scope-select"><span>练习范围</span><select id="level-select" aria-label="练习语法范围"><option value="ig" ${state.level==='ig'?'selected':''}>基础查询 · IG</option><option value="as" ${state.level==='as'?'selected':''}>进阶操作 · AS / AL</option></select></label><a class="avatar" href="#progress" aria-label="查看学习记录">Q</a></div></header>
  <main id="main" tabindex="-1">${content}</main><footer class="page-footer">在本机运行 SQL · 无需账号 <span>QueryPath / Learn by doing</span></footer></div>
  <nav class="mobile-nav" aria-label="移动端导航">${nav.slice(0,4).map(([id,i,title])=>`<a href="#${id}" ${current===id?'aria-current="page"':''} class="${current===id?'active':''}">${icon(i)}<span>${title.replace('SQL ','')}</span></a>`).join('')}<a href="#progress" ${current==='progress'?'aria-current="page"':''}>${icon('chart')}<span>记录</span></a></nav>`;
}
function heading(kicker,title,text,action=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1>${text?`<p>${text}</p>`:''}</div>${action}</div>`;}
function home(){const p=progress(),next=nextExercise();const list=lessons.filter(l=>l.level===state.level);return `
  ${heading('A LITTLE QUERY. A NEW DISCOVERY.','今天，向数据提个问题。','围绕 IG / AS / AL 考点，把纸上的 SQL 变成看得见的结果。',`<a href="#sources" class="text-link">查看语法参考 ${icon('arrow')}</a>`)}
  <section class="hero"><div class="hero-copy"><span class="hero-pill"><span></span>考纲内的 SQL，在浏览器中真正运行</span><h2>把好奇心，<br>写成一条查询。</h2><p>把 SELECT、筛选与统计，从会背变成会用。<br class="desktop-only">运行查询、观察结果，再回到考试题目中验证理解。</p><div class="hero-actions"><a class="button light" href="#lab">打开 SQL 实验室 ${icon('arrow')}</a><a class="hero-secondary" href="#exercise/${next.id}">${p.done?'继续上次学习':'从第一个查询开始'} ${icon('chevron')}</a></div><div class="hero-caption">真实数据表 <i></i> 即时运行 <i></i> 随时重置</div></div>
  <div class="hero-visual" aria-label="SQL 查询与结果示意"><div class="mini-editor"><div class="mini-editor-bar"><span class="window-dots">● ● ●</span><span>first_query.sql</span><span>SQL</span></div><pre><span class="line">1</span> <b>SELECT</b> Title, Price
<span class="line">2</span> <b>FROM</b> BOOK
<span class="line">3</span> <b>WHERE</b> Price &lt; <em>15</em>;</pre><div class="mini-editor-foot">${icon('check')} 查询已完成 <span>3 rows</span></div></div><div class="mini-result"><div class="mini-result-label">${icon('grid')} 查询结果 <span>预览示例</span></div><table><thead><tr><th>Title</th><th>Price</th></tr></thead><tbody><tr><td>Ocean Atlas</td><td>12.50</td></tr><tr><td>Small Worlds</td><td>9.80</td></tr><tr><td>The Quiet Forest</td><td>14.00</td></tr></tbody></table></div><span class="visual-spark spark-one">+</span><span class="visual-spark spark-two">+</span></div></section>
  <div class="stats-row"><a href="#progress" class="stat-card"><span class="stat-icon">${icon('check')}</span><div><strong>${p.done}<small> / ${p.total}</small></strong><span>已完成的任务</span></div><div class="stat-trail">从理解到实践</div></a><a href="#progress" class="stat-card"><span class="stat-icon blue">${icon('chart')}</span><div><strong>${p.independent}</strong><span>独立解决的任务</span></div><div class="stat-trail">每次尝试都被记录</div></a><button data-action="review" class="stat-card"><span class="stat-icon amber">${icon('reset')}</span><div><strong>${p.wrong}</strong><span>值得再试的任务</span></div><span class="stat-trail">温故，然后发现更多</span></button></div>
  <div class="home-columns"><section><div class="section-heading"><h2>你的下一步</h2><a href="#learn">完整学习指南 ${icon('arrow')}</a></div><a class="continue-card" href="#exercise/${next.id}"><span class="number-tag">${String(visibleExercises().indexOf(next)+1).padStart(2,'0')}</span><div><div class="tiny-label">${p.done?'CONTINUE EXPLORING':'START HERE'}</div><h3>${esc(next.title)}</h3><p>${esc(next.brief)}</p><span class="duration">${icon('clock')} ${next.minutes||5} 分钟 · ${esc(datasetById(next.dataset).name)}</span></div><span class="round-arrow">${icon('arrow')}</span></a><div class="section-heading spaced"><h2>从一个真实场景出发</h2><span class="muted-text">选择数据，开始探索</span></div><div class="dataset-cards">${datasets.map((d,i)=>`<button class="dataset-card" data-action="dataset" data-id="${d.id}"><span class="dataset-illustration tint-${i}">${icon(i===0?'book':i===1?'grid':'chart')}</span><strong>${esc(d.name)}</strong><span>${esc(d.description)}</span><small>打开数据集 ${icon('arrow')}</small></button>`).join('')}</div></section>
  <section class="path-card"><div class="section-heading"><h2>一步一步，读懂数据</h2><span class="badge muted">${state.level==='ig'?'基础路径':'进阶路径'}</span></div><div class="learning-path">${list.slice(0,4).map((l,i)=>{const done=l.exerciseIds.every(id=>state.attempts[id]?.passed);return `<a href="#lesson/${l.id}" class="path-step"><span class="step-number ${done?'done':''}">${done?icon('check'):i+1}</span><div><h3>${esc(l.title)}</h3><p>${esc(l.subtitle)}</p><small>${l.minutes} 分钟 · ${l.exerciseIds.length} 个练习</small></div>${icon('chevron')}</a>`;}).join('')}</div><a href="#learn" class="button secondary wide">浏览全部 ${list.length} 节指南 ${icon('arrow')}</a><div class="path-tip">${icon('help')} 不必按顺序学习。遇到一个问题，就从那里开始。</div></section></div>`;}
function exerciseCards(list){return list.length?list.map(e=>`<article class="task-card"><div class="task-top"><span class="task-kind">${e.kind==='sql'?'SQL 查询 / 操作':e.kind==='predict'?'读懂查询结果':'理解数据概念'}</span><button class="icon-button ${state.bookmarks.includes(e.id)?'bookmarked':''}" data-action="bookmark" data-id="${e.id}" aria-label="${state.bookmarks.includes(e.id)?'取消收藏':'收藏'}：${esc(e.title)}" aria-pressed="${state.bookmarks.includes(e.id)}">${icon('bookmark')}</button></div><a href="#exercise/${e.id}"><h3>${esc(e.title)}</h3><p>${esc(e.brief)}</p></a><div class="task-meta"><span>${icon('clock')} ${e.minutes||5} 分钟</span>${badge(e)}</div><a href="#exercise/${e.id}" class="task-start">${state.attempts[e.id]?'再次探索':'开始任务'} ${icon('arrow')}</a></article>`).join(''):`<div class="empty-state">${icon('search')}<h3>这里暂时没有匹配的任务</h3><p>试试更短的关键词，或清除当前筛选条件。</p><button class="button secondary" data-action="clear-filters">清除筛选</button></div>`;}
function filteredExercises(){return visibleExercises().filter(e=>`${e.title} ${e.brief} ${e.prompt} ${(e.objectives||[]).join(' ')}`.toLowerCase().includes(filters.search.toLowerCase())&&(filters.kind==='all'||e.kind===filters.kind)&&(filters.status==='all'||filters.status==='todo'&&!state.attempts[e.id]?.passed||filters.status==='wrong'&&state.attempts[e.id]?.tries>0&&!state.attempts[e.id].lastPassed||filters.status==='saved'&&state.bookmarks.includes(e.id)));}
function practice(){return `${heading('PRACTICE MAKES IT CLICK','让每一条查询都有用。','挑一个任务，观察数据，再写出你的解决方案。',`<a href="#exam" class="button secondary">${icon('clock')} 限时挑战</a>`)}<div class="filter-panel"><label class="search-field">${icon('search')}<input id="task-search" type="search" placeholder="搜索 SELECT、库存、连接…" aria-label="搜索练习任务" value="${esc(filters.search)}"></label><div class="filter-tabs" role="group" aria-label="任务状态">${[['all','全部'],['todo','待探索'],['wrong','再试一次'],['saved','已收藏']].map(([id,label])=>`<button data-action="filter" data-value="${id}" aria-pressed="${filters.status===id}" class="${filters.status===id?'selected':''}">${label}</button>`).join('')}</div><select id="kind-filter" aria-label="任务类型"><option value="all">所有任务类型</option>${[['sql','编写 SQL'],['predict','预测结果'],['concept','理解概念']].map(([id,t])=>`<option value="${id}" ${filters.kind===id?'selected':''}>${t}</option>`).join('')}</select></div><p class="result-count" id="task-count">${filteredExercises().length} 个任务 · ${state.level==='ig'?'单表查询基础':'关系查询与数据维护'}</p><div class="task-grid" id="task-list">${exerciseCards(filteredExercises())}</div>`;}
function learn(){return `${heading('UNDERSTAND. TRY. REMEMBER.','少一点背诵，多一点理解。','每节指南都从具体问题出发，用可运行的例子解释 SQL。')}<div class="lesson-grid">${lessons.filter(l=>l.level===state.level).map((l,i)=>{const count=l.exerciseIds.filter(id=>state.attempts[id]?.passed).length;return `<article class="lesson-card"><div class="lesson-top"><span class="lesson-number">${String(i+1).padStart(2,'0')}</span><span class="muted-text">${l.minutes} 分钟</span></div><h2><a href="#lesson/${l.id}">${esc(l.title)}</a></h2><p>${esc(l.subtitle)}</p><div class="keyword-tags">${l.keywords.map(k=>`<code>${esc(k)}</code>`).join('')}</div><div class="progress-line"><span style="width:${count/l.exerciseIds.length*100}%"></span></div><div class="lesson-bottom"><span>${count} / ${l.exerciseIds.length} 个任务完成</span><a href="#lesson/${l.id}">打开指南 ${icon('arrow')}</a></div></article>`;}).join('')}</div>`;}
function lesson(id){const l=lessons.find(l=>l.id===id);if(!l)return notFound();return `<a href="#learn" class="back-link">← 返回学习指南</a>${heading('LEARNING NOTE',esc(l.title),esc(l.subtitle))}<div class="reading-layout"><article class="reading-card">${l.body.map((p,i)=>`<div class="reading-section"><span class="reading-number">0${i+1}</span><p>${esc(p)}</p></div>`).join('')}<div class="code-sample"><div><span>亲手运行这个例子</span><button class="text-link" data-action="lesson-lab" data-id="${l.id}">在实验室打开 ${icon('arrow')}</button></div><pre><code>${esc(l.example)}</code></pre></div><div class="note">${icon('help')} 观察结果，再试着修改字段、条件或排序方式。实践比记住一条答案更重要。</div></article><aside class="lesson-tasks"><h2>动手试一试</h2>${l.exerciseIds.map(id=>byId(id)).filter(Boolean).map(e=>`<a href="#exercise/${e.id}" class="lesson-task"><span>${esc(e.title)}<small>${e.minutes||5} 分钟</small></span>${state.attempts[e.id]?.passed?icon('check'):icon('arrow')}</a>`).join('')}<a href="#sources" class="text-link">查阅语法与来源 ${icon('link')}</a></aside></div>`;}
function dataTable(columns,rows,{caption='',empty='没有符合条件的记录',max=100}={}){return `<div class="table-scroll" tabindex="0" role="region" aria-label="${esc(caption||'数据表')}" title="表格较宽时可左右滚动"><table class="data-table">${caption?`<caption>${esc(caption)}</caption>`:''}<thead><tr><th class="row-index" scope="col">#</th>${columns.map(c=>`<th scope="col">${esc(typeof c==='string'?c:c.name)}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,max).map((r,i)=>`<tr><th scope="row" class="row-index">${i+1}</th>${r.map(v=>`<td>${v===null?'<span class="null-value">NULL</span>':esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table>${!rows.length?`<div class="table-empty">${empty}</div>`:''}</div>${rows.length>max?`<p class="table-limit">显示前 ${max} 行，共 ${rows.length} 行。导出 CSV 可查看全部结果。</p>`:''}`;}
function taskTables(tables,e){const d=datasetById(e.dataset);const main=e.focusTables?.[0]||/\b(?:FROM|UPDATE|INTO)\s+([a-z0-9_$]+)/i.exec(e.solution||e.starter||'')?.[1]||d.tables[0];const preferred=tables.find(t=>t.name.toLowerCase()===main.toLowerCase());if(e.level==='ig'&&preferred)return [preferred];const ordered=displayTables(tables,d);return preferred?[preferred,...ordered.filter(t=>t!==preferred)]:ordered;}
function displayTables(tables,d){const order=d.tables;return [...tables].sort((a,b)=>(order.includes(a.name)?order.indexOf(a.name):999)-(order.includes(b.name)?order.indexOf(b.name):999));}
function databasePanel(tables){if(!tables.length)return '<div class="empty-inline">数据库中还没有表。试试 CREATE TABLE，或重置示例数据。</div>';tableIndex=Math.min(tableIndex,tables.length-1);const t=tables[tableIndex];return `<div class="table-tabs" role="group" aria-label="选择数据表">${tables.map((t,i)=>`<button data-action="table" data-index="${i}" aria-pressed="${i===tableIndex}" class="${i===tableIndex?'selected':''}">${icon('grid')} ${esc(t.name)} <small>${t.rows.length}</small></button>`).join('')}</div><details class="schema-details"><summary>字段与类型 <span>${t.columns.length} 个字段 · 点击展开</span></summary><div class="schema-chips">${t.columns.map(c=>`<span><code>${esc(c.name)}</code><small>${esc(c.type||'—')}${c.pk?' · 主键':''}</small></span>`).join('')}</div></details>${dataTable(t.columns,t.rows,{caption:t.name})}`;}
function outputPanel(value){if(!value)return `<div class="output-placeholder">${icon('play')}<div><strong>准备好发现答案了吗？</strong><p>运行 SQL，结果就会显示在这里。</p></div></div>`;if(value.error)return `<div class="feedback error" role="alert"><strong>这条语句还需要调整</strong><p>${esc(value.error)}</p></div>`;return `<div class="output-summary"><span class="success-text">${icon('check')} ${value.columns?.length?`查询完成 · ${value.rows.length} 行`:'执行完成'}</span><span>${esc(value.message||'')}</span>${value.columns?.length?'<button class="text-link" data-action="csv">导出 CSV</button>':''}</div>${value.notes?.length?`<div class="compat-notes">${value.notes.map(n=>`<p>${esc(n)}</p>`).join('')}</div>`:''}${value.columns?.length?dataTable(value.columns,value.rows,{caption:'查询结果'}):`<div class="mutation-summary">${icon('database')}<p>${esc(value.message||`数据已更新。${value.affected!=null?'影响 '+value.affected+' 条记录。':''}`)} 查看上方数据表，观察这次操作的变化。</p></div>`}`;}
function editor(sql,{lab=false,readonly=false}={}){return `<section class="editor-card"><div class="editor-header"><span>${icon('code')} ${lab?'playground.sql':'your_query.sql'}</span><div><button class="icon-button" data-action="font" aria-label="放大或恢复 SQL 字体">A↕</button><button class="icon-button" data-action="copy" aria-label="复制 SQL">${icon('link')}</button><button class="icon-button" data-action="reset-code" aria-label="恢复初始 SQL">${icon('reset')}</button></div></div><div class="editor-area"><div class="line-numbers" aria-hidden="true">${sql.split('\n').map((_,i)=>i+1).join('\n')}</div><textarea id="sql-editor" aria-label="SQL 编辑器" aria-describedby="editor-help" spellcheck="false" autocapitalize="off" autocomplete="off" autocorrect="off" ${readonly?'readonly':''} wrap="off">${esc(sql)}</textarea></div>${!readonly?`<div class="keyword-toolbar" aria-label="插入 SQL 关键词">${['SELECT','FROM','WHERE','AND','ORDER BY',...(state.level==='as'?['INNER JOIN','GROUP BY']:[])].map(k=>`<button data-action="insert" data-text="${k} ">${k}</button>`).join('')}</div>`:''}<p id="editor-help" class="sr-only">Ctrl 或 Command 加 Enter 运行 SQL。Tab 插入缩进；按 Escape 后再按 Tab 可移出编辑器。</p><div class="editor-actions"><span class="keyboard-hint">Ctrl / ⌘ + Enter 运行 · Esc + Tab 移出</span><div><button class="button ${lab?'primary':'secondary'}" data-action="run" ${busy?'disabled':''}>${icon('play')} ${busy?'正在运行…':'运行 SQL'}</button>${!lab&&!readonly?`<button class="button primary" data-action="submit" ${busy?'disabled':''}>${icon('check')} 检查结果</button>`:''}</div></div></section>`;}
function feedbackHtml(){if(!feedback)return '';return `<section class="feedback ${feedback.passed?'success':'error'}" id="answer-feedback" tabindex="-1" role="status"><div class="feedback-title">${icon(feedback.passed?'check':'help')}<h3>${feedback.passed?'做到了，数据给出了答案。':'再调整一下，离答案更近了。'}</h3></div><p>${esc(feedback.detail)}</p>${feedback.passed?`<p>${esc(byId(activeId)?.explanation||'')}</p>${solutionSeen?'<small>本次使用了参考答案，记录为辅助完成。</small>':''}<button class="button primary" data-action="next">下一个任务 ${icon('arrow')}</button>`:''}</section>`;}
async function exerciseView(id){const e=byId(id);if(!e){shell(notFound(),'practice');return;}if(e.level!==state.level){state.level=e.level;persist();}if(activeId!==id){activeId=id;feedback=null;result=null;editorDirty=false;exerciseTables=null;hintsShown=state.attempts[id]?.hints||0;solutionSeen=!!state.attempts[id]?.assisted;tableIndex=0;}state.lastExercise=id;persist();
  const d=datasetById(e.dataset);let tables=[];try{const db=await createEngine({SQL,level:e.level,seed:d.seed+(e.setup?'\n'+e.setup:'')});tables=taskTables(db.tables(),e);db.close();}catch(err){result={error:err.message};}
  if(route()[0]!=='exercise'||route()[1]!==id)return;if(exerciseTables)tables=exerciseTables;
  shell(`<a href="#practice" class="back-link">← 返回动手练习</a><div class="exercise-heading"><div><span class="eyebrow">${esc(d.name)} / ${e.kind==='sql'?'WRITE A QUERY':e.kind==='predict'?'READ THE RESULT':'UNDERSTAND THE DATA'}</span><h1>${esc(e.title)}</h1></div><button class="button secondary" data-action="bookmark" data-id="${id}" aria-pressed="${state.bookmarks.includes(id)}">${icon('bookmark')} ${state.bookmarks.includes(id)?'已收藏':'收藏任务'}</button></div><div class="workspace"><aside class="task-panel"><div class="task-panel-label">${icon('book')} 任务说明 ${badge(e)}</div><p class="english-prompt" lang="en">${esc(e.prompt)}</p><p class="task-brief">${esc(e.brief)}</p><div class="objectives"><h3>你会用到</h3><div class="keyword-tags">${(e.objectives||[]).map(s=>`<code>${esc(s)}</code>`).join('')}</div></div><div class="task-help"><h3>卡住了？一点提示</h3><div id="hints">${(e.hints||[]).slice(0,hintsShown).map((h,i)=>`<p><span>${i+1}</span>${esc(h)}</p>`).join('')}</div><button class="button secondary wide" data-action="hint" ${hintsShown>=(e.hints||[]).length?'disabled':''}>${icon('help')} ${hintsShown>=(e.hints||[]).length?'提示已全部展开':`查看提示 ${hintsShown+1} / ${(e.hints||[]).length}`}</button><button class="text-link solution-link" data-action="solution">查看参考思路与答案</button></div><div class="task-scope">${icon('database')} 每次运行使用初始数据，可放心尝试。</div></aside><div class="work-main"><section class="data-card"><div class="card-title"><h2>${icon('database')} 先认识数据</h2><span>${esc(d.name)}</span></div><div id="database-panel">${databasePanel(tables)}</div></section>${e.kind==='sql'?editor(state.drafts[id]??e.starter??''):e.kind==='predict'?`<div class="code-sample"><div>阅读这条查询</div><pre><code>${esc(e.starter||e.solution)}</code></pre></div><section class="answer-card"><label for="prediction">写下你预测的结果</label><p>每条记录一行，字段之间用英文逗号分隔，不写表头。</p><textarea id="prediction" rows="4" placeholder="例如：Alex,85" spellcheck="false">${esc(state.drafts[id]||'')}</textarea><button class="button primary" data-action="submit">${icon('check')} 检查预测</button></section>`:`<section class="answer-card"><fieldset><legend>选择你的答案</legend>${e.options.map((o,i)=>`<label class="choice"><input type="radio" name="concept" value="${i}" ${state.drafts[id]===String(i)?'checked':''}><span><b>${String.fromCharCode(65+i)}.</b> ${esc(o)}</span></label>`).join('')}</fieldset><button class="button primary" data-action="submit">${icon('check')} 检查答案</button></section>`}<div id="feedback-region">${feedbackHtml()}</div>${e.kind==='sql'?`<section class="result-card"><div class="card-title"><h2>${icon('grid')} 运行结果</h2><span>只在本机执行</span></div><div id="output-panel">${outputPanel(result)}</div></section>`:''}</div></div>`,'practice');
}
async function ensureLab(){if(labEngine)return;const d=datasetById(labDataset);try{labEngine=await createEngine({SQL,level:state.level,seed:d.seed,snapshot:state.lab?.dataset===d.id?state.lab.snapshot:undefined});}catch(error){labEngine=await createEngine({SQL,level:state.level,seed:d.seed});toast('实验室快照无法恢复，已载入初始示例。学习记录和 SQL 草稿仍保留。',true);}if(!state.lab?.sql)labSql=`SELECT *\nFROM ${d.tables[0]};`;state.lab={dataset:d.id,sql:labSql,snapshot:labEngine.export()};persist();}
async function lab(){await ensureLab();if(route()[0]!=='lab')return;shell(`${heading('YOUR SQL PLAYGROUND','一个问题，无限种探索。','直接操作数据，立即查看结果。所有改动都留在你的浏览器里。',`<button class="button secondary" data-action="reset-db">${icon('reset')} 重置数据</button>`)}<div class="lab-toolbar"><label>示例数据集 <select id="dataset-select" aria-label="实验室数据集">${datasets.map(d=>`<option value="${d.id}" ${d.id===labDataset?'selected':''}>${esc(d.name)}</option>`).join('')}</select></label><span class="muted-text">${esc(datasetById(labDataset).description)}</span><button class="text-link" data-action="templates">试一个查询模板 ${icon('arrow')}</button></div><div class="lab-layout"><div class="lab-main">${editor(labSql,{lab:true})}<section class="result-card"><div class="card-title"><h2>${icon('grid')} 查询结果</h2><span id="lab-save-status">${state.lab?'上次实验已恢复':'可随时恢复示例数据'}</span></div><div id="output-panel">${outputPanel(labResult)}</div></section></div><aside class="data-card lab-data"><div class="card-title"><h2>${icon('database')} 数据浏览器</h2><span>${esc(labEngine.export().databaseName||'本地沙盒')}</span></div><div id="database-panel">${databasePanel(displayTables(labEngine.tables(),datasetById(labDataset)))}</div><div class="lab-note"><strong>试着改变一个条件</strong><p>先运行 SELECT * 查看数据，再选择字段、添加 WHERE，观察每一步发生了什么。</p><a href="#sources" class="text-link">打开语法参考 ${icon('arrow')}</a></div></aside></div><div class="note">${icon('help')} ${state.level==='ig'?'当前使用基础查询范围。要尝试双表连接、创建表或修改数据，请在右上角切换到「进阶操作」。':'当前支持双表查询、创建表与数据维护。CREATE DATABASE 会进入一个新的空数据库；重置数据可回到示例。'}</div>`,'lab');}
function sources(){const ig=state.level==='ig';const rows=ig?[['选择字段','SELECT field FROM Table;','先决定要哪些列，再指定表。'],['筛选记录',"WHERE Score >= 80 AND Active = TRUE",'AND 同时满足；OR 满足任一条件。'],['排序','ORDER BY Score DESCENDING','也可用 DESC；ASCENDING / ASC 为升序。'],['统计记录','SELECT COUNT(*) FROM Table;','COUNT 统计条数；SUM(field) 累加数值。']]:[['连接两张表','FROM A INNER JOIN B ON A.ID = B.ID','用关联字段配对记录，避免遗漏连接条件。'],['分组统计','SELECT ClubID, AVG(Score) FROM STUDENT GROUP BY ClubID;','每个分组单独得到统计结果。'],['匹配文本',"WHERE FirstName LIKE 'A%'",'% 匹配任意长度字符；_ 匹配一个字符。'],['维护数据',"UPDATE STUDENT SET Score = 90 WHERE StudentID = 1;",'INSERT 增加、UPDATE 修改、DELETE 删除。'],['定义结构','CREATE TABLE TEAM (ID INTEGER, Name VARCHAR(30), PRIMARY KEY(ID));','可用 ALTER TABLE 添加字段、主键、外键。']];return `${heading('A REFERENCE, NOT A RULEBOOK','需要的时候，回来查一查。','把语法和实际用途放在一起。先理解，再动手。')}<section class="reference-grid">${rows.map(([title,sql,desc])=>`<article class="reference-card"><h2>${title}</h2><pre><code>${esc(sql)}</code></pre><p>${desc}</p></article>`).join('')}</section><section class="reference-note"><h2>这些细节，会让查询更清楚</h2><ul><li>文本用引号包围；数字不需要引号。推荐单引号，兼容试卷出现的双引号。</li><li>COUNT(*) 数记录；SUM(field) 加总字段；AS 还支持 AVG(field)。</li><li>没有 ORDER BY 时，不要依赖结果的展示顺序；排序字段可以不在 SELECT 列表中。</li><li>执行成功不等于解决了问题。检查筛选边界、输出列和是否需要去掉不相关的记录。</li><li>练习器支持所选范围的语法。超出范围的提示不代表该语法在所有数据库中都错误。</li></ul></section><details class="evidence-section"><summary><span><strong>内容依据与考试适用范围</strong><small>查看考纲、逐卷研究及兼容写法的来源</small></span><span class="badge">41 份试卷 + 评分方案</span></summary><div class="evidence-content"><p>适用于 IGCSE 0478（2026–2028）和 AS / 完整 A Level 9618（2026、2027–2029）。SQL 位于 AS 基础内容，完整 A Level 沿用这部分知识。历史评分认可的写法只作为对应题目的证据，不保证未来所有题目都同样接受。</p><div class="source-links"><a href="https://www.cambridgeinternational.org/Images/697167-2026-2028-syllabus.pdf" target="_blank" rel="noopener">0478 考纲 · §9 ↗</a><a href="https://www.cambridgeinternational.org/Images/697372-2026-syllabus.pdf" target="_blank" rel="noopener">9618 2026 · §8.3 ↗</a><a href="https://www.cambridgeinternational.org/Images/721397-2027-2029-syllabus.pdf" target="_blank" rel="noopener">9618 2027–2029 · §8.3 ↗</a><a href="./docs/research/ig-paper-audit.md" target="_blank" rel="noopener">IG 逐卷分析 ↗</a><a href="./docs/research/as-paper-audit.md" target="_blank" rel="noopener">AS 逐卷分析 ↗</a></div><p>核查日期：2026-10-24。21 份 IG Paper 2 + 20 份不同 SQL 内容的 AS Paper 1，均核对对应评分方案。本站练习全部为原创，反馈用于学习，不是官方评分。</p><div class="filter-tabs" role="group" aria-label="研究证据筛选">${[['all','全部'],['0478','IG'],['9618','AS / AL']].map(([id,label])=>`<button data-action="source-filter" data-value="${id}" aria-pressed="${sourceFilter===id}" class="${sourceFilter===id?'selected':''}">${label}</button>`).join('')}</div><div id="evidence-list">${evidenceList()}</div></div></details><section class="reference-note"><h2>关于本地实验室</h2><p>SQL 由本地 SQLite 引擎运行，兼容层处理考试中的排序拼写、布尔值和日期表示。表结构操作会检查主外键；SQLite 的类型行为与商用数据库不完全相同，例如 VARCHAR(n) 不自动限制文本长度。练习不模拟用户权限、并发事务或服务器部署。</p><p>应用不收集个人信息。学习记录保存在当前浏览器；更换设备请先导出备份。使用不同端口、浏览器或网址时，本地记录也会分开。</p></section>`;}
function evidenceList(){const list=evidence.filter(e=>sourceFilter==='all'||e.id.startsWith(sourceFilter));return list.length?list.map(e=>`<article class="evidence-row"><div><strong>${esc(e.id.replace(/_/g,' '))}</strong><span>Q${esc(e.question)} · QP p.${esc(e.pages.qp.join(', '))} / MS p.${esc(e.pages.ms.join(', '))}</span><p>${esc(e.analysis)}</p><div class="keyword-tags">${e.topics.map(k=>`<code>${esc(k)}</code>`).join('')}</div>${e.allowances?.length?`<details><summary>写法与适用边界</summary>${e.allowances.map(a=>`<p>${esc(a)}</p>`).join('')}</details>`:''}</div><div><a href="${esc(e.qpUrl)}" target="_blank" rel="noopener">试卷 ↗</a><a href="${esc(e.msUrl)}" target="_blank" rel="noopener">评分方案 ↗</a></div></article>`).join(''):'<p>研究记录正在读取。若暂不可用，仍可打开上方逐卷分析。</p>';}
function recoveryAvailable(){try{return !!localStorage.getItem(STORAGE_KEY+'.recovery');}catch{return false;}}
function progressPage(){const p=progress();return `${heading('YOUR LEARNING, YOUR PACE','每次尝试，都算数。','记录你的进步，带着已经理解的知识继续探索。',`<button class="button secondary" data-action="export">${icon('download')} 导出学习记录</button>`)}<div class="stats-row"><div class="stat-card"><span class="stat-icon">${icon('check')}</span><div><strong>${p.done}</strong><span>已完成任务</span></div></div><div class="stat-card"><span class="stat-icon blue">${icon('chart')}</span><div><strong>${p.independent}</strong><span>独立完成</span></div></div><div class="stat-card"><span class="stat-icon amber">${icon('reset')}</span><div><strong>${p.wrong}</strong><span>待复习</span></div></div></div><div class="progress-layout"><section class="panel"><div class="section-heading"><h2>最近的探索</h2><button class="text-link" data-action="review">复习错题 ${icon('arrow')}</button></div>${state.history.length?state.history.slice(-12).reverse().map(a=>{const e=byId(a.id);return e?`<a href="#exercise/${e.id}" class="history-row"><span class="history-status ${a.passed?'success-text':'warm-text'}">${icon(a.passed?'check':'reset')}</span><div><strong>${esc(e.title)}</strong><small>${new Date(a.at).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})} · ${a.assisted?'使用参考答案':'自主尝试'}</small></div><span>${a.passed?'完成':'再试一次'}</span>${icon('chevron')}</a>`:'';}).join(''):`<div class="empty-state">${icon('chart')}<h3>你的第一条查询，值得记录</h3><p>完成一个任务后，学习记录会出现在这里。</p><a href="#practice" class="button primary">开始探索 ${icon('arrow')}</a></div>`}</section><section class="panel settings-panel"><h2>把进度带在身边</h2><p>导出 JSON 备份，在另一台设备上导入。导入会合并完成记录，不清除现有进度。</p><button class="button secondary wide" data-action="export">${icon('download')} 导出备份</button><label class="button secondary wide file-button">${icon('upload')} 导入备份<input type="file" id="import-file" accept=".json,application/json"></label>${recoveryAvailable()?'<button class="button secondary wide" data-action="recovery">导出损坏记录的恢复文件</button>':''}<div class="settings-divider"></div><h2>让学习更舒适</h2><button class="button secondary wide" data-action="theme">${icon('sun')} ${state.theme==='dark'?'切换浅色模式':'切换深色模式'}</button><button class="button secondary wide" data-action="install">${icon('download')} 离线与安装说明</button><a class="button secondary wide" href="#sources">${icon('book')} 语法与来源说明</a><div class="settings-divider"></div><button class="text-link danger-text" data-action="clear-progress">清除本机学习记录</button><p class="small-note">数据只属于当前浏览器。清除浏览器数据也会删除学习记录，建议定期导出。</p></section></div>`;}
function exam(){const x=state.exam;if(!x||x.finished){const report=x?.finished;return `${heading('A SMALL CHALLENGE','给自己一段专注的时间。','用 15 分钟，独立解决 5 个小任务。挑战结束后统一查看反馈。')}<section class="challenge-start panel"><span class="challenge-icon">${icon('clock')}</span><h2>${report?'这一轮探索已结束':'准备好，测试一下自己的理解。'}</h2>${report?`<p class="challenge-score">${x.ids.filter(id=>x.answers[id]?.passed).length}<span> / ${x.ids.length}</span></p><p>这是学习任务的结果，不对应官方考试分数或等级。</p><div class="challenge-results">${x.ids.map(id=>`<a href="#exercise/${id}"><span>${esc(byId(id)?.title||id)}</span><span>${x.answers[id]?.passed?'✓ 已解决':'↻ 再练一次'}</span></a>`).join('')}</div>`:'<p>题目会从当前范围选取，包含编写、阅读与理解任务。倒计时关闭页面后仍继续；答案和进度自动保存在本机。</p>'}<button class="button primary" data-action="start-exam">${report?'再来一轮':'开始 15 分钟挑战'} ${icon('arrow')}</button></section>`;}
const e=byId(x.ids[x.index]);if(!e){state.exam=null;persist();return exam();}return `${heading('FOCUS MODE',`任务 ${x.index+1} / ${x.ids.length}`,esc(e.title),'<span class="exam-clock" id="exam-clock"></span>')}<div class="exam-progress">${x.ids.map((id,i)=>`<button data-action="exam-index" data-index="${i}" class="${i===x.index?'active':''}" aria-label="跳转第 ${i+1} 题">${i+1}${x.answers[id]?.submitted?' ✓':''}</button>`).join('')}</div><section class="panel exam-panel"><p class="english-prompt" lang="en">${esc(e.prompt)}</p><p>${esc(e.brief)}</p><details id="exam-data"><summary>查看 ${esc(datasetById(e.dataset).name)} 数据</summary><div id="exam-table-content">正在准备数据…</div></details>${e.kind==='sql'?`<label for="exam-answer">你的 SQL</label><textarea id="exam-answer" class="exam-answer" rows="7" spellcheck="false" autocapitalize="off">${esc(x.answers[e.id]?.value??e.starter??'')}</textarea>`:e.kind==='predict'?`<pre class="code-sample">${esc(e.starter||e.solution)}</pre><label for="exam-answer">预测结果（每条记录一行，字段用英文逗号分隔）</label><textarea id="exam-answer" rows="4">${esc(x.answers[e.id]?.value||'')}</textarea>`:`<fieldset><legend>选择答案</legend>${e.options.map((o,i)=>`<label class="choice"><input type="radio" name="exam-concept" value="${i}" ${x.answers[e.id]?.value===String(i)?'checked':''}><span>${esc(o)}</span></label>`).join('')}</fieldset>`}<div class="exam-actions"><button class="button secondary" data-action="exam-save">保存本题 ${icon('check')}</button><button class="button primary" data-action="${x.index<x.ids.length-1?'exam-next':'finish-exam'}">${x.index<x.ids.length-1?'下一题':'结束并查看结果'} ${icon('arrow')}</button></div><p class="small-note" id="exam-save-note">${x.answers[e.id]?.submitted?'本题已保存，可继续修改。':'输入内容会自动保存，结束时统一检查。'}</p></section><button class="text-link" data-action="finish-exam">提前结束挑战</button>`;}
function notFound(){return `<div class="empty-state"><h1>这里没有找到对应内容</h1><p>链接可能已失效，回到学习空间继续吧。</p><a class="button primary" href="#home">返回首页</a></div>`;}
async function render(){clearInterval(examTimer);const [page,id]=route();if(!SQL){shell(`<div class="empty-state">${engineError?`<h1>SQL 引擎未能启动</h1><p>${esc(engineError)}</p><button class="button primary" data-action="reload">重新加载</button>`:'<h1>正在准备数据与 SQL 引擎…</h1><p>首次载入完成后，即可在本机练习。</p>'}</div>`,page);return;}if(page==='exercise')await exerciseView(id);else if(page==='lab')await lab();else{const renderer={home,practice,learn,lesson:()=>lesson(id),sources,progress:progressPage,exam};shell((renderer[page]||notFound)(),page);if(page==='exam'&&state.exam&&!state.exam.finished){updateTimer();examTimer=setInterval(updateTimer,1000);const e=byId(state.exam.ids[state.exam.index]);const db=await createEngine({SQL,level:e.level,seed:datasetById(e.dataset).seed+(e.setup?'\n'+e.setup:'')});const box=document.querySelector('#exam-table-content');if(box)box.innerHTML=db.tables().map(t=>dataTable(t.columns,t.rows,{caption:t.name})).join('');db.close();}}}
function updateLineNumbers(){const el=document.querySelector('#sql-editor');const numbers=document.querySelector('.line-numbers');if(el&&numbers){numbers.textContent=el.value.split('\n').map((_,i)=>i+1).join('\n');numbers.scrollTop=el.scrollTop;}}
function currentSql(){return document.querySelector('#sql-editor')?.value||'';}
function saveDraft(value){editorDirty=true;feedback=null;const feedbackBox=document.querySelector('#feedback-region');if(feedbackBox)feedbackBox.innerHTML='';const output=document.querySelector('#output-panel');const oldResult=route()[0]==='lab'?labResult:result;if(output&&oldResult)output.innerHTML='<p class="stale-notice">SQL 已修改，以下是上次运行的结果。请重新运行。</p>'+outputPanel(oldResult);if(route()[0]==='lab'){labSql=value;if(state.lab)state.lab.sql=value;}else if(activeId)state.drafts[activeId]=value;clearTimeout(saveTimer);saveTimer=setTimeout(persist,250);}
function setBusy(value){busy=value;document.querySelectorAll('[data-action="run"],[data-action="submit"]').forEach(b=>b.disabled=value);}
async function runSql(){if(busy)return;const isLab=route()[0]==='lab',sql=currentSql();if(!sql.trim()){toast('先写一条 SQL，再运行。',true);document.querySelector('#sql-editor')?.focus();return;}saveDraft(sql);editorDirty=false;setBusy(true);let db;try{if(isLab){await ensureLab();db=labEngine;}else{const e=byId(activeId);db=await createEngine({SQL,level:e.level,seed:datasetById(e.dataset).seed+(e.setup?'\n'+e.setup:'')});}const output=db.run(sql,{level:state.level});if(isLab){labResult=output;state.lab={dataset:labDataset,sql:labSql,snapshot:labEngine.export()};persist();document.querySelector('#database-panel').innerHTML=databasePanel(displayTables(labEngine.tables(),datasetById(labDataset)));const status=document.querySelector('#lab-save-status');if(status)status.textContent='实验已保存到本机';}else {result=output;exerciseTables=taskTables(db.tables(),byId(activeId));const dataPanel=document.querySelector('#database-panel');if(dataPanel)dataPanel.innerHTML=databasePanel(exerciseTables);}}catch(error){if(isLab)labResult={error:error.message};else result={error:error.message};}finally{if(!isLab)db?.close();setBusy(false);const output=document.querySelector('#output-panel');if(output)output.innerHTML=outputPanel(isLab?labResult:result);}}
function normalizePrediction(text,ordered){const lines=String(text).trim().split(/\r?\n/).filter(s=>s.trim()).map(s=>s.split(',').map(v=>v.trim().replace(/^['"]|['"]$/g,'')).join(','));return (ordered?lines:lines.sort()).join('\n');}
async function checkAnswer(e,value){if(e.kind==='sql')return gradeSql(SQL,e,datasetById(e.dataset),value);if(e.kind==='concept')return {passed:String(value)===String(e.answer),detail:String(value)===String(e.answer)?'理解正确。':'这个选项还不符合情境。回到字段、记录或键的用途再想一想。'};const passed=normalizePrediction(value,e.ordered)===normalizePrediction(e.expected,e.ordered);return {passed,detail:passed?'你正确地读出了查询结果。':'预测结果还不一致。检查输出字段、记录数量、条件与排序；每条记录单独一行，不写表头。'};}
async function submit(){if(busy)return;const e=byId(activeId);const value=e.kind==='sql'?currentSql():e.kind==='predict'?document.querySelector('#prediction').value:document.querySelector('input[name="concept"]:checked')?.value;if(value==null||!String(value).trim()){toast('请先填写你的答案。',true);return;}state.drafts[e.id]=value;setBusy(true);try{feedback=await checkAnswer(e,value);if(feedback.got)result=feedback.got;recordAttempt(state,e.id,feedback.passed,{assisted:solutionSeen});persist();}catch(error){feedback={passed:false,detail:error.message};recordAttempt(state,e.id,false,{assisted:solutionSeen});persist();}finally{setBusy(false);document.querySelector('#feedback-region').innerHTML=feedbackHtml();if(document.querySelector('#output-panel'))document.querySelector('#output-panel').innerHTML=outputPanel(result);document.querySelector('#answer-feedback')?.focus({preventScroll:true});document.querySelector('#answer-feedback')?.scrollIntoView({behavior:'smooth',block:'nearest'});}}
function modal(title,html,actions=[]){const dialog=document.querySelector('#dialog');dialog.innerHTML=`<div class="dialog-header"><h2>${esc(title)}</h2><button class="icon-button" data-action="close-dialog" aria-label="关闭对话框">${icon('close')}</button></div><div class="dialog-body">${html}</div><div class="dialog-actions">${actions.map(a=>`<button class="button ${a.danger?'danger':a.primary?'primary':'secondary'}" data-dialog-action="${a.id}">${esc(a.label)}</button>`).join('')}</div>`;dialog.showModal();for(const a of actions)dialog.querySelector(`[data-dialog-action="${a.id}"]`).onclick=async()=>{dialog.close();await a.run();};}
async function changeDataset(id,sql){if(labEngine){labEngine.close();labEngine=null;}labDataset=id;labResult=null;tableIndex=0;state.lab=null;await ensureLab();labSql=sql||`SELECT *\nFROM ${datasetById(id).tables[0]};`;state.lab={dataset:id,sql:labSql,snapshot:labEngine.export()};persist();if(route()[0]==='lab')await render();else go('lab');}
function saveExamAnswer(submitted=false){const x=state.exam;if(!x||x.finished)return;const id=x.ids[x.index],e=byId(id);const value=e.kind==='concept'?document.querySelector('input[name="exam-concept"]:checked')?.value:document.querySelector('#exam-answer')?.value;if(value!=null)x.answers[id]={...(x.answers[id]||{}),value,submitted:submitted||x.answers[id]?.submitted};persist();}
function updateTimer(){const x=state.exam;if(!x||x.finished)return;const seconds=Math.max(0,Math.ceil((x.deadline-Date.now())/1000));const el=document.querySelector('#exam-clock');if(el)el.textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;if(seconds===0)finishExam();}
async function finishExam(){if(busy||!state.exam||state.exam.finished)return;if(route()[0]==='exam')saveExamAnswer();busy=true;clearInterval(examTimer);const x=state.exam;for(const id of x.ids){const e=byId(id),value=x.answers[id]?.value;let checked={passed:false};if(value!=null&&String(value).trim()){try{checked=await checkAnswer(e,value);}catch(error){checked={passed:false,detail:error.message};}recordAttempt(state,id,checked.passed);}x.answers[id]={...(x.answers[id]||{}),passed:checked.passed,detail:checked.detail};}x.finished=true;busy=false;persist();if(route()[0]==='exam')render();else toast('限时挑战已结束。可在「动手练习 → 限时挑战」查看结果。');}
let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
document.addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;if(b.disabled)return;
  if(action==='run')return runSql();if(action==='submit')return submit();
  if(action==='reload')return location.reload();
  if(action==='theme'){state.theme=state.theme==='dark'?'light':'dark';persist();document.documentElement.dataset.theme=state.theme;await render();return;}
  if(action==='close-dialog'){document.querySelector('#dialog').close();return;}
  if(action==='bookmark'){const id=b.dataset.id;state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];persist();b.setAttribute('aria-pressed',String(state.bookmarks.includes(id)));b.classList.toggle('bookmarked',state.bookmarks.includes(id));toast(state.bookmarks.includes(id)?'已加入收藏':'已取消收藏');if(route()[0]==='practice'&&filters.status==='saved')updateTaskList();return;}
  if(action==='filter'){filters.status=b.dataset.value;return render();}if(action==='clear-filters'){filters={search:'',status:'all',kind:'all'};return render();}
  if(action==='review'){filters.status='wrong';filters.search='';go('practice');return;}
  if(action==='dataset'){if(state.lab)modal('切换示例数据集', '<p>当前实验室的修改会被新示例替换。学习进度与练习草稿会保留。</p>',[{id:'cancel',label:'保留当前实验',run:()=>{}},{id:'switch',label:'切换数据集',primary:true,run:()=>changeDataset(b.dataset.id)}]);else await changeDataset(b.dataset.id);return;}
  if(action==='lesson-lab'){const l=lessons.find(x=>x.id===b.dataset.id);modal('在实验室运行示例', '<p>将载入这节指南的数据与示例查询，并替换当前实验室数据。</p>',[{id:'cancel',label:'取消',run:()=>{}},{id:'open',label:'载入示例',primary:true,run:()=>changeDataset(l.dataset,l.example)}]);return;}
  if(action==='table'){tableIndex=Number(b.dataset.index);if(route()[0]==='lab')document.querySelector('#database-panel').innerHTML=databasePanel(displayTables(labEngine.tables(),datasetById(labDataset)));else if(exerciseTables){const dataPanel=document.querySelector('#database-panel');if(dataPanel)dataPanel.innerHTML=databasePanel(exerciseTables);}else{const e=byId(activeId),db=await createEngine({SQL,seed:datasetById(e.dataset).seed+(e.setup?'\n'+e.setup:''),level:e.level});document.querySelector('#database-panel').innerHTML=databasePanel(taskTables(db.tables(),e));db.close();}return;}
  if(action==='insert'){const el=document.querySelector('#sql-editor');if(!el)return;el.setRangeText(b.dataset.text,el.selectionStart,el.selectionEnd,'end');el.focus();saveDraft(el.value);updateLineNumbers();return;}
  if(action==='copy'){try{await navigator.clipboard.writeText(currentSql());toast('SQL 已复制');}catch{const el=document.querySelector('#sql-editor');el.focus();el.select();toast('已选中 SQL，请使用系统的复制操作。');}return;}
  if(action==='font'){document.querySelector('.editor-area').classList.toggle('large-font');return;}
  if(action==='reset-code'){modal('恢复初始 SQL', '<p>当前编辑内容将被替换。数据库内容不会改变。</p>',[{id:'cancel',label:'取消',run:()=>{}},{id:'reset',label:'恢复模板',primary:true,run:()=>{const el=document.querySelector('#sql-editor');el.value=route()[0]==='lab'?`SELECT *\nFROM ${datasetById(labDataset).tables[0]};`:byId(activeId).starter||'';saveDraft(el.value);updateLineNumbers();el.focus();}}]);return;}
  if(action==='reset-db'){modal('重新开始这个实验', '<p>示例数据会恢复到初始状态，当前新增的表和数据修改会被清除。你写的 SQL 会保留。</p>',[{id:'cancel',label:'保留当前数据',run:()=>{}},{id:'reset',label:'重置示例数据',primary:true,run:async()=>{labEngine.reset();labResult=null;tableIndex=0;state.lab={dataset:labDataset,sql:labSql,snapshot:labEngine.export()};persist();await render();toast('示例数据已恢复');}}]);return;}
  if(action==='hint'){const e=byId(activeId);hintsShown=Math.min(hintsShown+1,e.hints.length);state.attempts[e.id]={...(state.attempts[e.id]||{}),hints:hintsShown};persist();const container=document.querySelector('#hints');container.innerHTML=e.hints.slice(0,hintsShown).map((h,i)=>`<p><span>${i+1}</span>${esc(h)}</p>`).join('');b.disabled=hintsShown===e.hints.length;b.innerHTML=`${icon('help')} ${b.disabled?'提示已全部展开':`查看提示 ${hintsShown+1} / ${e.hints.length}`}`;return;}
  if(action==='solution'){const e=byId(activeId);modal('先理解，再看答案','<p>查看参考答案后，本题的后续完成会记录为「辅助完成」。你可以先尝试提示，或继续查看思路。</p>',[{id:'cancel',label:'继续尝试',run:()=>{}},{id:'reveal',label:'查看参考答案',primary:true,run:()=>{solutionSeen=true;state.attempts[e.id]={...(state.attempts[e.id]||{}),assisted:true};persist();modal('参考思路与答案',`<p>${esc(e.explanation)}</p><pre class="solution-code">${esc(e.kind==='concept'?e.options[e.answer]:e.kind==='predict'?e.expected:e.solution)}</pre><p class="small-note">正确 SQL 可以有多种写法。理解为什么能得到这个结果，比记住文字更重要。</p>`,[{id:'close',label:'返回任务',primary:true,run:()=>{}}]);}}]);return;}
  if(action==='next'){const list=visibleExercises(),i=list.findIndex(e=>e.id===activeId);go(i<list.length-1?`exercise/${list[i+1].id}`:'progress');return;}
  if(action==='recovery'){download('querypath-recovery.json',localStorage.getItem(STORAGE_KEY+'.recovery')||'');return;}
  if(action==='export'){download(`querypath-backup-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2));toast('学习备份已导出');return;}
  if(action==='csv'){const r=route()[0]==='lab'?labResult:result;if(!r?.columns?.length)return;const quote=v=>`"${String(v??'').replace(/"/g,'""')}"`;download('query-results.csv','\uFEFF'+[r.columns,...r.rows].map(row=>row.map(quote).join(',')).join('\r\n'),'text/csv;charset=utf-8');return;}
  if(action==='source-filter'){sourceFilter=b.dataset.value;document.querySelector('#evidence-list').innerHTML=evidenceList();b.parentElement.querySelectorAll('button').forEach(el=>{el.classList.toggle('selected',el===b);el.setAttribute('aria-pressed',String(el===b));});return;}
  if(action==='templates'){const list=exercises.filter(e=>e.dataset===labDataset&&e.kind==='sql'&&e.level===state.level).slice(0,5);modal('选择一个问题开始探索',`<p>载入 SQL 模板不会重置当前数据。</p>${list.map(e=>`<button class="template-option" data-template="${e.id}"><strong>${esc(e.title)}</strong><code>${esc(e.solution)}</code></button>`).join('')||'<p>这个数据集在当前范围还没有模板，可以直接编写 SELECT 查询。</p>'}`);document.querySelectorAll('[data-template]').forEach(el=>el.onclick=()=>{const e=byId(el.dataset.template);labSql=e.solution;document.querySelector('#sql-editor').value=labSql;saveDraft(labSql);updateLineNumbers();document.querySelector('#dialog').close();});return;}
  if(action==='install'){if(installPrompt){await installPrompt.prompt();installPrompt=null;return;}modal('在不同设备上使用',`<p><strong>电脑：</strong>运行本地服务后访问当前网址。支持安装的浏览器可在地址栏菜单中安装应用。</p><p><strong>iPhone / iPad：</strong>使用 Safari 打开 HTTPS 网站，点分享 → 添加到主屏幕。Android 可使用浏览器菜单中的安装选项。</p><p><strong>离线：</strong>${offlineReady?'此浏览器已经缓存核心学习内容，可断网使用。':'核心资源尚未完成离线缓存。请保持联网首次加载；离线与安装功能需要 HTTPS 或 localhost。'}</p><p><strong>同一 Wi-Fi：</strong>手机或平板可访问电脑启动时显示的局域网地址；普通 HTTP 局域网地址可以在线操作，但不能启用离线 PWA。</p><p class="small-note">各设备进度独立，通过导出/导入备份迁移。外部试卷链接仍需要网络。</p>`,[{id:'ok',label:'知道了',primary:true,run:()=>{}}]);return;}
  if(action==='clear-progress'){modal('清除这台设备的学习记录','<p>这会删除任务草稿、完成记录、收藏和实验室数据。此操作无法撤销，建议先导出备份。</p>',[{id:'cancel',label:'取消',run:()=>{}},{id:'export',label:'先导出备份',run:()=>download('querypath-backup.json',JSON.stringify(state,null,2))},{id:'clear',label:'确认清除',danger:true,run:()=>{localStorage.removeItem(STORAGE_KEY);location.reload();}}]);return;}
  if(action==='start-exam'){const list=visibleExercises();const shuffled=[...list].sort(()=>Math.random()-.5).slice(0,5);state.exam={ids:shuffled.map(e=>e.id),index:0,deadline:Date.now()+15*60000,answers:{},finished:false};persist();return render();}
  if(action==='exam-save'){saveExamAnswer(true);document.querySelector('#exam-save-note').textContent='本题已保存，可继续修改。';toast('本题答案已保存');return;}
  if(action==='exam-next'){saveExamAnswer(true);state.exam.index++;persist();return render();}
  if(action==='exam-index'){saveExamAnswer();state.exam.index=Number(b.dataset.index);persist();return render();}
  if(action==='finish-exam'){modal('结束本轮挑战', '<p>所有已填写答案会统一检查，未填写的任务记为未完成。</p>',[{id:'cancel',label:'继续作答',run:()=>{}},{id:'finish',label:'结束并查看结果',primary:true,run:finishExam}]);return;}
});
function updateTaskList(){document.querySelector('#task-list').innerHTML=exerciseCards(filteredExercises());document.querySelector('#task-count').textContent=`${filteredExercises().length} 个匹配任务`;}
document.addEventListener('input',e=>{if(e.target.id==='sql-editor'){saveDraft(e.target.value);updateLineNumbers();}if(e.target.id==='task-search'){filters.search=e.target.value;updateTaskList();}if(e.target.id==='prediction'){state.drafts[activeId]=e.target.value;persist();}if(e.target.id==='exam-answer')saveExamAnswer();});
document.addEventListener('change',async event=>{const el=event.target;if(el.id==='level-select'){state.level=el.value;if(state.level==='ig'&&state.year==='2029')state.year='2028';persist();if(route()[0]==='exercise'||route()[0]==='lesson')go('practice');else render();}if(el.id==='kind-filter'){filters.kind=el.value;updateTaskList();}if(el.name==='concept'){state.drafts[activeId]=el.value;persist();}if(el.name==='exam-concept')saveExamAnswer();if(el.id==='dataset-select'){const id=el.value;el.value=labDataset;modal('切换数据集','<p>当前实验室数据将被新示例替换。学习记录和练习草稿会保留。</p>',[{id:'cancel',label:'取消',run:()=>{}},{id:'switch',label:'切换',primary:true,run:()=>changeDataset(id)}]);}if(el.id==='import-file'){const file=el.files[0];if(!file)return;if(file.size>8000000){toast('备份文件过大，请选择小于 8 MB 的 JSON 文件。',true);return;}try{const imported=validateBackup(JSON.parse(await file.text()));modal('合并学习记录',`<p>检测到 ${Object.keys(imported.attempts).length} 条任务记录、${Object.keys(imported.drafts).length} 份草稿。完成记录与收藏将合并，同一任务保留较新的记录；已有草稿优先保留。当前实验室数据不会被替换。</p>`,[{id:'cancel',label:'取消',run:()=>{}},{id:'import',label:'合并导入',primary:true,run:()=>{state=mergeBackup(state,imported);persist();render();toast('学习记录已合并');}}]);}catch(error){toast(`无法导入：${error.message}`,true);}el.value='';}});
document.addEventListener('keydown',e=>{if(e.target.id==='sql-editor'){if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();runSql();}if(e.key==='Escape'){e.target.dataset.escapeTab='true';}if(e.key==='Tab'&&e.target.dataset.escapeTab==='true'){delete e.target.dataset.escapeTab;return;}if(e.key==='Tab'&&!e.shiftKey){e.preventDefault();e.target.setRangeText('  ',e.target.selectionStart,e.target.selectionEnd,'end');saveDraft(e.target.value);updateLineNumbers();}}});
document.addEventListener('scroll',e=>{if(e.target.id==='sql-editor'){const numbers=document.querySelector('.line-numbers');if(numbers)numbers.scrollTop=e.target.scrollTop;}},true);
document.querySelector('#dialog').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.close();});
window.addEventListener('hashchange',()=>{clearTimeout(saveTimer);persist();render();window.scrollTo({top:0,behavior:'instant'});});
window.addEventListener('pagehide',()=>{clearTimeout(saveTimer);persist();});
window.addEventListener('online',()=>toast('网络已恢复'));window.addEventListener('offline',()=>toast(offlineReady?'已离线，核心学习内容仍可使用。':'当前已离线，已载入的内容仍可使用。'));
async function boot(){await render();try{if(!window.initSqlJs)await new Promise((resolve,reject)=>{const script=document.querySelector('script[data-sql-runtime]');script.addEventListener('load',resolve,{once:true});script.addEventListener('error',()=>reject(new Error('无法加载 SQL 引擎，请刷新页面重试。')),{once:true});});SQL=await window.initSqlJs({locateFile:f=>assetUrl(`vendor/${f}`)});await render();if(loaded.warning)toast(loaded.warning,true);}catch(e){engineError=e.message;render();}try{const all=await Promise.all(['ig','as'].map(async code=>{const r=await fetch(assetUrl(`docs/research/${code}-papers.json`));if(!r.ok)throw new Error('读取失败');return r.json();}));evidence=all.flat();if(route()[0]==='sources')document.querySelector('#evidence-list').innerHTML=evidenceList();}catch{}if('serviceWorker'in navigator&&window.isSecureContext){try{await navigator.serviceWorker.register(assetUrl('sw.js'),{scope:appBase.href});await navigator.serviceWorker.ready;offlineReady=true;const note=document.querySelector('.local-note span:last-child');if(note)note.textContent='离线学习已就绪';}catch{}}}
boot();
